  bx_jiangshi: {"tier": 0, "zh": "符咒殭屍", "en": "Talisman Jiangshi", "bio": {"zh": "穿著紫色官服、頭戴官帽的殭屍，額前貼著一張黃符，雙臂直直伸向前，一跳一跳地走。符一掉下來，就再也停不住了。", "en": "A corpse in a purple official robe and cap with a yellow talisman stuck to its brow, arms stretched straight out, moving in hops. If the talisman falls off, nothing can stop it."}, "habitat": {"zh": "義莊、古墓與夜路", "en": "Coffin houses, old tombs and night roads"}},
  bx_shanxiao: {"tier": 0, "zh": "山魈", "en": "Shanxiao", "bio": {"zh": "深山裡的山精：一圈金色鬃毛，紅鼻樑、藍色的皺紋臉頰，只有一隻大腳，跳起來卻比人跑得還快。愛偷旅人的鹽和火種，被叫出名字就會逃走。", "en": "An imp of the deep mountains: a ring of golden mane, a red nose ridge and blue ribbed cheeks, and only one big foot, yet it hops faster than a man can run. It steals travellers' salt and tinder, and flees when called by its name."}, "habitat": {"zh": "深山密林", "en": "Deep mountain forest"}},
  bx_fox: {"tier": 0, "zh": "九尾狐", "en": "Nine-Tailed Fox", "bio": {"zh": "修行千年的金毛狐狸，身後九條尾巴像扇子一樣展開，尾尖燃著雪白的狐火。眼睛細長帶紅，會讓迷路的旅人一直在原地打轉。", "en": "A golden fox with a thousand years of cultivation, nine tails fanned out behind it, pale fox-fire burning at their tips. Its long red eyes can keep a lost traveller walking in circles all night."}, "habitat": {"zh": "月夜的竹林與古墳", "en": "Bamboo groves and old graves on moonlit nights"}},
  bx_jiao: {"tier": 0, "zh": "江蛟", "en": "River Jiao", "bio": {"zh": "還沒化成龍的蛟，青綠鱗甲、淡黃腹甲，頭上一對短角和長鬚。藏在江心最深的潭底，一翻身就掀起大浪，渡船常被牠攪翻。", "en": "A jiao that has not yet become a dragon: green-teal scales, a pale yellow belly, two short horns and long whiskers. It hides in the deepest pool mid-river, and when it turns over the waves rise and ferries capsize."}, "habitat": {"zh": "大江的深潭與急流", "en": "Deep pools and rapids of the great river"}},
